"use client";

import { useRouter, useParams } from "next/navigation";
import { useQuery } from "@tanstack/react-query";
import { useEffect, useState } from "react";
import { fetchProduct, fetchCategories } from "@/components/product/api";
import ProductForm from "@/components/product/ProductForm";
import ProductImageUploader from "@/components/product/ProductImageUploader";
import { Product, Category, ProductStatus } from "@/types/product";
import AccessDenied from "@/components/common/AccessDenied";
import { ToastContainer } from "react-toastify";

const EditDraftProduct = () => {
  const router = useRouter();
  const { productId } = useParams() as { productId: string };

  const [initialValues, setInitialValues] = useState<Partial<Product>>({
    productName: "",
    detail: "",
    price: 0,
    weight: 0,
    productCategory: "",
  });

  const { data: product, isLoading: isProductLoading } = useQuery<Product>({
    queryKey: ["product", productId],
    queryFn: () => fetchProduct(productId),
    enabled: !!productId,
  });

  const { data: categories, isLoading: isCategoriesLoading } = useQuery<Category[]>({
    queryKey: ["categories"],
    queryFn: fetchCategories,
  });

  const [isUnauthorized, setIsUnauthorized] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false); // To track submission state

  useEffect(() => {
    if (product) {
      console.log("Fetched product:", product);
      console.log("Product status:", product.status);

      if (product.status !== ProductStatus.DRAFT) {
        console.warn("Unauthorized access: Redirecting to /403...");
        setIsUnauthorized(true);
        setTimeout(() => router.push("/403"), 2000);
        return;
      }

      const matchedCategory = categories?.find((c) => c.categoryName === product.productCategory);

      setInitialValues({
        productName: product.productName || "",
        detail: product.detail || "",
        price: product.price || 0,
        weight: product.weight || 0,
        productCategory: matchedCategory ? String(matchedCategory.categoryId) : "",
      });
    }
  }, [product, categories, router]);

  if (isProductLoading || isCategoriesLoading) return <div>Loading...</div>;

  if (isUnauthorized) return <AccessDenied />;

  const handleSubmit = () => {
    // Check if the form is already submitting
    if (isSubmitting) return;

    setIsSubmitting(true); // Set submitting state to true

    const form = document.querySelector("form");
    if (form) {
      form.requestSubmit(); // Trigger form submission
    }

    // Optionally, you can reset the submitting state to false after a successful submission or error.
    // For now, we'll leave it as is until you handle the response from the API.
  };

  return (
    <div className="p-6 bg-white shadow-md rounded-lg">
      <ToastContainer />
      <h2 className="text-3xl text-gray-500 font-semibold mb-4">Edit Product Draft</h2>
      {initialValues.productName ? (
        <>
          <ProductForm
            initialValues={initialValues}
            categories={categories || []}
            productId={productId}
          />

          {/* Update Button */}
          <div className="mt-6">
            <button
              type="button"
              onClick={handleSubmit}
              disabled={isSubmitting} // Disable while submitting
              className={`${
                isSubmitting ? "bg-gray-300" : "bg-blue-500"
              } text-white py-2 px-4 rounded-md`}
            >
              {isSubmitting ? "Submitting..." : "Update"}
            </button>
          </div>

          <div className="mt-6">
            <h3 className="text-xl text-gray-500 font-semibold mb-2">Product Images</h3>
            <ProductImageUploader productId={productId} />
          </div>
        </>
      ) : (
        <div>Loading product details...</div>
      )}
    </div>
  );
};

export default EditDraftProduct;
